<?php
declare(strict_types=1);
const ADMIN_EMAIL='admin@example.com';
const ADMIN_EMAILS=[ADMIN_EMAIL,'admin@example.com','admin@example.com'];
const BOOKING_EMAIL='Info@besttoursdubai.com';
const SITE_ORIGIN='https://besttoursdubai.com';
$categoryNames=['general'=>'Dubai Safari Park','attractions'=>'Attraction tickets','desert-safari'=>'Desert safaris','city-tours'=>'City tours','adventure'=>'Adventure','luxury'=>'Luxury experiences'];
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function validImage($s){return is_string($s)&&((str_starts_with($s,'/')&&!str_starts_with($s,'//'))||str_starts_with($s,'https://'));}
function plain($s){return trim(preg_replace('/\s+/u',' ',html_entity_decode(strip_tags((string)$s),ENT_QUOTES,'UTF-8')));}
function cleanHtml($s){$s=preg_replace('~<(script|style|iframe|object|form|noscript)\b[^>]*>[\s\S]*?</\1>~i','',(string)$s);$s=preg_replace('~<!--[\s\S]*?-->~','',$s);return preg_replace_callback('~</?([a-z][a-z0-9]*)\b([^>]*)>~i',function($m){$name=strtolower($m[1]);if(!in_array($name,['p','h2','h3','h4','h5','h6','strong','b','em','i','u','s','ul','ol','li','blockquote','a','br','hr','img','table','thead','tbody','tr','th','td','section','div','span','details','summary']))return '';if(str_starts_with($m[0],'</'))return '</'.$name.'>';preg_match_all('~([\w-]+)\s*=\s*["\']([^"\']*)["\']~',$m[2],$attrs,PREG_SET_ORDER);$v=[];foreach($attrs as $a)$v[strtolower($a[1])]=html_entity_decode($a[2],ENT_QUOTES,'UTF-8');$safe='';if($name==='a'&&isset($v['href'])&&preg_match('~^(https?://|mailto:|tel:|/[^/]|#)~i',$v['href']))$safe.=' href="'.e($v['href']).'"';if($name==='img'&&validImage($v['src']??''))$safe.=' src="'.e($v['src']).'" alt="'.e($v['alt']??'').'" loading="lazy"';if(isset($v['class']))$safe.=' class="'.e($v['class']).'"';return '<'.$name.$safe.'>';},$s);}
function activePrice($p){return $p['experience']['discountPrice']??$p['experience']['price']??null;}
function bookingPackages($p){return $p['experience']['packages']?:[['name'=>$p['type']==='attraction'?'Ticket request':'Standard package','mode'=>'per_person','adultPrice'=>activePrice($p)??0,'childPrice'=>activePrice($p)??0,'unitPrice'=>0,'unitLabel'=>'person','capacity'=>0]];}
function publicPath($p){if($p['path']==='/')return '/';$slug=trim($p['seo']['slug']??'');return $slug?substr($p['path'],0,strrpos($p['path'],'/')+1).$slug:$p['path'];}
function packageTotal($p,$adults,$children,$units){if($p['mode']==='per_person')return $adults*$p['adultPrice']+$children*$p['childPrice'];if($p['mode']==='flat')return $p['unitPrice'];if($p['mode']==='per_group')return ceil(($adults+$children)/max(1,$p['capacity']))*$p['unitPrice'];return $units*$p['unitPrice'];}
function addonTotal($a,$quantity,$adults,$children){if(!$quantity||($a['requestOnly']??false))return 0;return match($a['mode']){'per_person'=>($adults+$children)*$a['price'],'per_adult'=>$adults*$a['price'],'per_child'=>$children*$a['price'],'flat'=>$a['price'],default=>$quantity*$a['price']};}
function db(){static $db;if(!$db){$folder=__DIR__.'/storage';if(!is_dir($folder))mkdir($folder,0700,true);$db=new PDO('sqlite:'.$folder.'/cms.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS cms(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS login_tokens(hash TEXT PRIMARY KEY,expires INTEGER NOT NULL,email TEXT NOT NULL); CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,time INTEGER NOT NULL,count INTEGER NOT NULL);');if(!in_array('email',array_column($db->query('PRAGMA table_info(login_tokens)')->fetchAll(PDO::FETCH_ASSOC),'name'))) $db->exec("ALTER TABLE login_tokens ADD COLUMN email TEXT NOT NULL DEFAULT 'admin@example.com'");initializePasswordAccounts($db);migratePublicEmail($db);chmod($folder.'/cms.sqlite',0600);}return $db;}
function query($sql,$args=[]){$q=db()->prepare($sql);$q->execute($args);return $q;}
function save($key,$value){if(($key==='settings'||str_starts_with($key,'page:'))&&!headers_sent())header('X-LiteSpeed-Purge: *');query('INSERT INTO cms VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at',[$key,json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),gmdate('c')]);}
function allContent(bool $includeDeleted=false){$seed=json_decode(file_get_contents(__DIR__.'/pages.json'),true,512,JSON_THROW_ON_ERROR);$settings=json_decode(file_get_contents(__DIR__.'/settings.json'),true);$map=[];foreach(query("SELECT key,value FROM cms WHERE key='settings' OR key LIKE 'page:%'")->fetchAll(PDO::FETCH_ASSOC) as $r)$map[$r['key']]=json_decode($r['value'],true);foreach($seed as &$p)if(isset($map['page:'.$p['path']]))$p=$map['page:'.$p['path']];unset($p);foreach($map as $key=>$p)if(str_starts_with($key,'page:')&&!in_array($p['path'],array_column($seed,'path'),true))$seed[]=$p;return ['settings'=>array_merge($settings,$map['settings']??[]),'pages'=>$includeDeleted?$seed:array_values(array_filter($seed,fn($p)=>empty($p['deletedAt'])))];}
function sessionStart(){if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);session_name('btd_session');session_start();}}
function admin(){sessionStart();return passwordSessionValid()&&!($_SESSION['mustChangePassword']??true);}
function requireAdmin(){if(!admin())jsonResponse(['error'=>'Administrator access required.'],403);}
function jsonResponse($v,$code=200){http_response_code($code);header('Content-Type: application/json;charset=utf-8');header('Cache-Control: no-store');echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function requireOrigin(){if(($_SERVER['HTTP_ORIGIN']??'')!==SITE_ORIGIN)jsonResponse(['error'=>'Invalid request origin.'],403);}
function limitRequests($kind,$max,$window){$key=$kind.':'.hash('sha256',$_SERVER['REMOTE_ADDR']??'');db()->beginTransaction();$r=query('SELECT time,count FROM rate_limits WHERE key=?',[$key])->fetch(PDO::FETCH_ASSOC);$count=$r&&$r['time']>time()-$window?$r['count']+1:1;$start=$count===1?time():$r['time'];query('INSERT INTO rate_limits VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET time=excluded.time,count=excluded.count',[$key,$start,$count]);db()->commit();if($count>$max)jsonResponse(['error'=>'Please wait before trying again.'],429);}
function notify($subject,$body,$reply='',$to=BOOKING_EMAIL){require_once __DIR__.'/mail-smtp.php';return sendBusinessMail((string)$subject,(string)$body,(string)$reply,(string)$to);}
require_once __DIR__.'/password-auth.php';

function migratePublicEmail(PDO $db):void{
 if($db->query("SELECT 1 FROM cms WHERE key='setup:contact-email-v2'")->fetchColumn())return;
 $row=$db->query("SELECT value FROM cms WHERE key='settings'")->fetchColumn();
 if($row){$settings=json_decode($row,true,512,JSON_THROW_ON_ERROR);$settings['email']='Bestoursdubai@gmail.com';$update=$db->prepare("UPDATE cms SET value=?,updated_at=? WHERE key='settings'");$update->execute([json_encode($settings,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),gmdate('c')]);}
 $db->exec("INSERT INTO cms VALUES('setup:contact-email-v2','true',datetime('now'))");
}
